// Valid Wordle words (~14,855). Source:
// https://gist.github.com/dracos/dd0668f281e685bad51479e5acaadb93
// Stored as a single concatenated string of 5-letter words for compact bundling.
const RAW = '';
export const WORDS: readonly string[] = Array.from({ length: RAW.length / 5 }, (_, i) => RAW.slice(i * 5, i * 5 + 5));
